public class InnerChannelChannelLoggingInfoFactory(Action<Humidifier.MSK.ChannelTypes.ChannelLoggingInfo> factoryAction = null) : SubResourceFactory<Humidifier.MSK.ChannelTypes.ChannelLoggingInfo>
{

    internal InnerChannelS3LogDestinationFactory S3Factory { get; set; }

    internal InnerChannelFirehoseLogDestinationFactory FirehoseFactory { get; set; }

    internal InnerChannelCloudWatchLogsLogDestinationFactory CloudWatchLogsFactory { get; set; }

    protected override Humidifier.MSK.ChannelTypes.ChannelLoggingInfo Create()
    {
        var channelLoggingInfoResult = CreateChannelLoggingInfo();
        factoryAction?.Invoke(channelLoggingInfoResult);

        return channelLoggingInfoResult;
    }

    private Humidifier.MSK.ChannelTypes.ChannelLoggingInfo CreateChannelLoggingInfo()
    {
        var channelLoggingInfoResult = new Humidifier.MSK.ChannelTypes.ChannelLoggingInfo();

        return channelLoggingInfoResult;
    }
    public override void CreateChildren(Humidifier.MSK.ChannelTypes.ChannelLoggingInfo result)
    {
        base.CreateChildren(result);

        result.S3 ??= S3Factory?.Build();
        result.Firehose ??= FirehoseFactory?.Build();
        result.CloudWatchLogs ??= CloudWatchLogsFactory?.Build();
    }

} // End Of Class

